package dev.cazajefes;

import java.util.*;
import org.bukkit.*;
import org.bukkit.entity.*;
import org.bukkit.event.*;
import org.bukkit.event.entity.*;
import org.bukkit.event.player.*;
import org.bukkit.inventory.ItemStack;
import org.bukkit.potion.*;
import org.bukkit.util.Vector;

/** Weapon-specific combos: snapshot at launch, activate after accepted damage, bounded transient state. */
final class RangedRares implements Listener {
 record Pair(UUID owner,UUID target,String power){}
 record Progress(int count,long until,boolean ranged){}
 record Ready(int level,long until){}
 record Shot(UUID owner,Map<String,Integer> powers,Location origin,double force,long until){}
 record Action(String power,int level,Pair pair,boolean trigger){}
 record Hit(Player owner,LivingEntity target,Shot shot,List<Action> actions,boolean shield){}
 private final CazaJefesPlugin plugin;
 private final RelicItems items;
 private final Map<UUID,Shot> shots=new HashMap<>();
 private final Map<UUID,Boolean> gravityRestore=new HashMap<>();
 private final Map<Pair,Progress> combos=new HashMap<>();
 private final Map<String,Long> cooldowns=new HashMap<>();
 private final Map<UUID,Ready> sidesteps=new HashMap<>();
 private final Map<UUID,Long> moved=new HashMap<>();
 private final Map<EntityDamageByEntityEvent,Hit> pending=new WeakHashMap<>();
 private final Set<org.bukkit.scheduler.BukkitTask> tasks=new HashSet<>();
 private final org.bukkit.scheduler.BukkitTask cleaner;
 static boolean secondary;
 RangedRares(CazaJefesPlugin plugin,RelicItems items){this.plugin=plugin;this.items=items;cleaner=plugin.getServer().getScheduler().runTaskTimer(plugin,this::prune,20,20);}
 static double bonus(int level){return 1+.15*Math.max(1,Math.min(4,level));}
 static boolean ready(long now,long expires){return now>=expires;}
 static boolean fullyCharged(double force){return force>=.95;}
 static boolean alternate(boolean previous,boolean current){return previous!=current;}
 private long now(){return System.currentTimeMillis();}
 private String key(Player p,String id){return p.getUniqueId()+":"+id;}
 private boolean available(Player p,String id){return ready(now(),cooldowns.getOrDefault(key(p,id),0L));}
 private void spend(Player p,String id){cooldowns.put(key(p,id),now()+RangedRareCatalog.get(id).cooldown()*1000L);}
 private Map<String,Integer> powers(ItemStack weapon){Map<String,Integer> out=new LinkedHashMap<>();if(weapon==null)return out;for(var spec:RangedRareCatalog.ALL)if(spec.weapon()==weapon.getType()&&items.saturationCost(weapon,spec.id())>=0){int n=items.activePropertyLevel(weapon,spec.id());if(n>0)out.put(spec.id(),Math.min(spec.max(),n));}return Map.copyOf(out);}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void bow(EntityShootBowEvent e){if(!(e.getEntity() instanceof Player p)||!CombatGuard.eligible(p))return;Map<String,Integer> powers=powers(e.getBow());if(powers.isEmpty()||shots.size()>=1024)return;Shot shot=new Shot(p.getUniqueId(),powers,p.getLocation().clone(),e.getForce(),now()+60000);shots.put(e.getProjectile().getUniqueId(),shot);
  Integer level=powers.get("ojo_tormenta");long stillSince=moved.computeIfAbsent(p.getUniqueId(),id->now());if(level!=null&&fullyCharged(e.getForce())&&now()-stillSince>=1500&&available(p,"ojo_tormenta")){spend(p,"ojo_tormenta");Entity projectile=e.getProjectile();later(1,()->{if(projectile.isValid()){projectile.setVelocity(projectile.getVelocity().multiply(1+.1*level));boolean gravity=projectile.hasGravity();gravityRestore.put(projectile.getUniqueId(),gravity);projectile.setGravity(false);later(10,()->{gravityRestore.remove(projectile.getUniqueId());if(projectile.isValid())projectile.setGravity(gravity);});fx(projectile.getLocation(),Particle.END_ROD,8);}});}}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void trident(ProjectileLaunchEvent e){if(e.getEntity() instanceof Trident t&&t.getShooter() instanceof Player p&&CombatGuard.eligible(p)&&shots.size()<1024){Map<String,Integer> powers=powers(t.getItemStack());if(!powers.isEmpty())shots.put(t.getUniqueId(),new Shot(p.getUniqueId(),powers,p.getLocation().clone(),1,now()+60000));}}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void move(PlayerMoveEvent e){if(e.getTo()!=null&&(!e.getFrom().getWorld().equals(e.getTo().getWorld())||e.getFrom().distanceSquared(e.getTo())>.0004)){if(e.getPlayer().getInventory().getItemInMainHand().getType()==Material.BOW||moved.containsKey(e.getPlayer().getUniqueId()))moved.put(e.getPlayer().getUniqueId(),now());}}
 private Progress progress(Pair key){Progress p=combos.get(key);return p!=null&&p.until()>now()?p:null;}
 static double fractureBonus(int level){return 1+.1*Math.max(1,Math.min(3,level));}
 private boolean enemy(Player owner,LivingEntity target){return !target.equals(owner)&&!target.isDead()&&target.isValid()&&target.getWorld().equals(owner.getWorld())&&(!(target instanceof Player p)||RareCombat.enemy(owner,p));}
 @EventHandler(priority=EventPriority.HIGH,ignoreCancelled=true)public void prepare(EntityDamageByEntityEvent e){if(secondary||!(e.getEntity() instanceof LivingEntity target))return;Shot shot=shots.get(e.getDamager().getUniqueId());Player owner;if(shot!=null){owner=Bukkit.getPlayer(shot.owner());if(shot.until()<=now())return;}else if(e.getDamager() instanceof Player p){owner=p;Map<String,Integer> powers=powers(p.getInventory().getItemInMainHand());shot=new Shot(p.getUniqueId(),powers,p.getLocation().clone(),0,now()+1000);}else return;
  if(owner==null||!CombatGuard.eligible(owner)||!enemy(owner,target))return;boolean shield=false;if(!RareCombat.accepted(e.isCancelled(),e.getFinalDamage()))return;boolean ranged=e.getDamager() instanceof Projectile;List<Action> actions=new ArrayList<>();
  Pair fracturePair=new Pair(owner.getUniqueId(),target.getUniqueId(),"quebranto");Progress fracture=progress(fracturePair);if(!ranged&&fracture!=null){SafeDamage.scale(e,fractureBonus(fracture.count()));actions.add(new Action("quebranto_consumir",fracture.count(),fracturePair,true));}
  for(var entry:shot.powers().entrySet()){String id=entry.getKey();int n=entry.getValue();if(!available(owner,id))continue;Pair pair=new Pair(owner.getUniqueId(),target.getUniqueId(),id);Progress old=progress(pair);boolean trigger=RangedComboRules.trigger(id,old==null?0:old.count(),old!=null&&old.ranged(),ranged,fullyCharged(shot.force()),shot.origin().distanceSquared(target.getLocation()),shield);
   if((id.equals("marca_cazador")||id.equals("ancla_abisal"))&&trigger&&e.getFinalDamage()>0)SafeDamage.scale(e,bonus(n));actions.add(new Action(id,n,pair,trigger));}
  pending.put(e,new Hit(owner,target,shot,List.copyOf(actions),shield));}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void commit(EntityDamageByEntityEvent e){Hit hit=pending.remove(e);if(hit==null)return;boolean damage=RareCombat.accepted(e.isCancelled(),e.getFinalDamage());boolean ranged=e.getDamager() instanceof Projectile;for(Action a:hit.actions()){if(!damage)continue;String id=a.power();if(id.equals("quebranto_consumir")){combos.remove(a.pair());later(1,()->{if(hit.target().isValid())fx(hit.target().getLocation().add(0,1,0),Particle.CRIT,10);});continue;}if(a.trigger()){if(!available(hit.owner(),id))continue;spend(hit.owner(),id);combos.remove(a.pair());later(1,()->activate(hit,a));}else if(damage){Progress old=progress(a.pair());boolean store=RangedComboRules.stores(id,ranged,fullyCharged(hit.shot().force()),hit.shot().origin().distanceSquared(hit.target().getLocation()));if(store&&combos.size()<8192)combos.put(a.pair(),new Progress((old==null?0:old.count())+1,now()+(Set.of("cerrojo_vacio","estela_boreal","conductor_tempestades").contains(id)?8000:6000),ranged));}}}
 private void activate(Hit hit,Action action){Player owner=hit.owner();LivingEntity target=hit.target();if(!owner.isOnline()||!CombatGuard.eligible(owner)||!owner.getWorld().equals(target.getWorld()))return;String id=action.power();int n=action.level();if(id.equals("relevo_fantasma")){sidesteps.put(owner.getUniqueId(),new Ready(n,now()+4000));owner.sendActionBar(net.kyori.adventure.text.Component.text("Relevo Fantasma · agáchate para esquivar",net.kyori.adventure.text.format.NamedTextColor.AQUA));return;}if(id.equals("pulso_retorno")){var heal=new EntityRegainHealthEvent(owner,n,EntityRegainHealthEvent.RegainReason.CUSTOM);Bukkit.getPluginManager().callEvent(heal);if(!heal.isCancelled()&&Double.isFinite(heal.getAmount())&&heal.getAmount()>0)owner.setHealth(Math.min(owner.getMaxHealth(),owner.getHealth()+Math.min(n,heal.getAmount())));fx(owner.getLocation().add(0,1,0),Particle.HEART,5);return;}if(!enemy(owner,target))return;
  switch(id){case "cerrojo_vacio","ancla_abisal"->pull(owner,target,n);case "estela_boreal"->{target.addPotionEffect(new PotionEffect(PotionEffectType.SLOWNESS,60,n-1));fx(target.getLocation().add(0,1,0),Particle.SNOWFLAKE,16);}case "marea_ascendente"->{for(LivingEntity other:nearby(owner,target.getLocation(),4)){Vector away=other.getLocation().toVector().subtract(target.getLocation().toVector());if(away.lengthSquared()<.01)away=owner.getLocation().getDirection();other.setVelocity(away.setY(0).normalize().multiply(.5+.18*n).setY(.35));}ring(target.getLocation(),4,Particle.SPLASH);}case "quebranto"->{if(combos.size()<8192)combos.put(action.pair(),new Progress(n,now()+4000,true));fx(target.getLocation().add(0,1,0),Particle.CRIT,10);}case "conductor_tempestades"->{for(LivingEntity other:nearby(owner,target.getLocation(),4))if(!other.equals(target)&&target.hasLineOfSight(other)){fx(other.getLocation().add(0,1,0),Particle.ELECTRIC_SPARK,16);damage(owner,other,2*n);break;}}default->fx(target.getLocation().add(0,1,0),Particle.ENCHANT,8);}}
 private void pull(Player owner,LivingEntity target,int level){Vector v=owner.getLocation().toVector().subtract(target.getLocation().toVector()).setY(0);if(v.lengthSquared()>.1)target.setVelocity(v.normalize().multiply(.3+.15*level).setY(.2));fx(target.getLocation().add(0,1,0),Particle.REVERSE_PORTAL,12);}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void impact(ProjectileHitEvent e){Shot shot=shots.get(e.getEntity().getUniqueId());if(shot==null||shot.until()<=now()||e.getHitEntity()!=null||e.getHitBlock()==null)return;Player owner=Bukkit.getPlayer(shot.owner());if(owner==null||!CombatGuard.eligible(owner))return;String id=shot.powers().containsKey("carga_inestable")?"carga_inestable":shot.powers().containsKey("resaca")?"resaca":null;if(id==null||!available(owner,id)||tasks.size()>128)return;spend(owner,id);int n=shot.powers().get(id);Location at=e.getHitBlock().getLocation().add(.5,.5,.5);if(e.getHitBlockFace()!=null)at.add(e.getHitBlockFace().getDirection().multiply(.65));ring(at,3,id.equals("resaca")?Particle.SPLASH:Particle.ELECTRIC_SPARK);
  if(id.equals("carga_inestable")){for(int t:new int[]{12,24,36})later(t,()->{if(valid(owner,at)){ring(at,3,Particle.ELECTRIC_SPARK);at.getWorld().playSound(at,Sound.BLOCK_AMETHYST_BLOCK_CHIME,.35f,1.4f);}});}
  if(id.equals("carga_inestable"))later(40,()->{if(valid(owner,at)){fx(at,Particle.EXPLOSION,1);at.getWorld().playSound(at,Sound.ENTITY_GENERIC_EXPLODE,.6f,1.6f);for(LivingEntity target:nearby(owner,at,3))damage(owner,target,2*n);}});else for(int t=0;t<3;t++)later(t*20+1,()->{if(valid(owner,at)){ring(at,3,Particle.SPLASH);for(LivingEntity target:nearby(owner,at,3))target.addPotionEffect(new PotionEffect(PotionEffectType.SLOWNESS,40,n-1));}});}
 @EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void sneak(PlayerToggleSneakEvent e){if(!e.isSneaking())return;Ready r=sidesteps.remove(e.getPlayer().getUniqueId());Player p=e.getPlayer();if(r==null||r.until()<=now()||!CombatGuard.eligible(p))return;Vector facing=p.getLocation().getDirection().setY(0);if(facing.lengthSquared()<.01)return;Vector side=new Vector(-facing.getZ(),0,facing.getX()).normalize();Location from=p.getLocation();for(double d=.25;d<=r.level();d+=.25){Location step=from.clone().add(side.clone().multiply(d));if(!EncounterSafety.clear(p,step)||!step.clone().subtract(0,.1,0).getBlock().getType().isSolid())return;}Location to=from.clone().add(side.multiply(r.level()));later(1,()->{if(valid(p,to)&&p.getLocation().distanceSquared(from)<1&&EncounterSafety.clear(p,to)&&p.teleport(to,PlayerTeleportEvent.TeleportCause.PLUGIN))fx(from.add(0,1,0),Particle.REVERSE_PORTAL,12);});}
 private boolean valid(Player owner,Location at){return owner.isOnline()&&CombatGuard.eligible(owner)&&owner.getWorld().equals(at.getWorld())&&at.getWorld().isChunkLoaded(at.getBlockX()>>4,at.getBlockZ()>>4);}
 private List<LivingEntity> nearby(Player owner,Location at,double radius){if(!valid(owner,at))return List.of();return at.getWorld().getNearbyEntities(at,radius,radius,radius).stream().filter(e->e instanceof LivingEntity l&&enemy(owner,l)&&l.getLocation().distanceSquared(at)<=radius*radius&&owner.hasLineOfSight(l)&&visibleFrom(at,l)).map(e->(LivingEntity)e).sorted(Comparator.comparingDouble(e->e.getLocation().distanceSquared(at))).limit(8).toList();}
 private boolean visibleFrom(Location at,LivingEntity target){Location origin=at.clone().add(0,.05,0);Vector direction=target.getEyeLocation().toVector().subtract(origin.toVector());double length=direction.length();return length<.01||at.getWorld().rayTraceBlocks(origin,direction.multiply(1/length),length,FluidCollisionMode.NEVER,true)==null;}
 private void damage(Player owner,LivingEntity target,double amount){if(!enemy(owner,target))return;secondary=true;try{target.damage(amount,owner);}finally{secondary=false;}}
 private void fx(Location at,Particle particle,int count){CosmeticFX.emit(particle,at,count,.2,.3,.2,0);}
 private void ring(Location at,double radius,Particle particle){for(int i=0;i<24;i++){double angle=i*Math.PI/12;CosmeticFX.emit(particle,at.clone().add(Math.cos(angle)*radius,.15,Math.sin(angle)*radius),1);}}
 private void later(long delay,Runnable action){if(tasks.size()>=256)return;final org.bukkit.scheduler.BukkitTask[] task={null};task[0]=plugin.getServer().getScheduler().runTaskLater(plugin,()->{tasks.remove(task[0]);action.run();},delay);tasks.add(task[0]);}
 private void prune(){long now=now();shots.entrySet().removeIf(entry->{Entity entity=Bukkit.getEntity(entry.getKey());return entry.getValue().until()<=now||entity==null||!entity.isValid()||entity instanceof AbstractArrow arrow&&arrow.isInBlock();});combos.values().removeIf(v->v.until()<=now);cooldowns.values().removeIf(v->v<=now);sidesteps.values().removeIf(v->v.until()<=now);moved.keySet().removeIf(id->{Player p=Bukkit.getPlayer(id);return p==null||!p.isOnline();});}
 @EventHandler public void quit(PlayerQuitEvent e){UUID id=e.getPlayer().getUniqueId();moved.remove(id);sidesteps.remove(id);combos.keySet().removeIf(k->k.owner().equals(id)||k.target().equals(id));shots.values().removeIf(s->s.owner().equals(id));}
 void stop(){for(var entry:gravityRestore.entrySet()){Entity entity=Bukkit.getEntity(entry.getKey());if(entity!=null&&entity.isValid())entity.setGravity(entry.getValue());}gravityRestore.clear();cleaner.cancel();for(var t:tasks)t.cancel();tasks.clear();shots.clear();combos.clear();cooldowns.clear();sidesteps.clear();moved.clear();pending.clear();secondary=false;}
}
